H.background();
// a x + b = c x + d. We let the user pick slope-gap and intercept-gap to land
// in each regime. mode: 0 one solution, 1 no solution, 2 infinite.
const mode = Math.max(0, Math.min(2, Math.round(P.mode)));
const b = P.b, gap = P.gap;
// build the two sides so the chosen regime is guaranteed:
let a, c, d;
if (mode === 0) { a = 2; c = -1; d = b + gap; }          // different slopes -> one solution
else if (mode === 1) { a = 1; c = 1; d = b + Math.max(0.5, Math.abs(gap) + 0.5); } // parallel, b != d
else { a = 1; c = 1; d = b; }                              // identical line
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
v.fn(x => a * x + b, { color: H.colors.accent, width: 3 });
v.fn(x => c * x + d, { color: H.colors.accent2, width: (mode === 2 ? 6 : 3), dash: (mode === 2 ? [2, 6] : null) });
H.text("No-solution vs infinite-solution:  a·x + b = c·x + d", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
let label;
if (mode === 0) {
  const xs = (d - b) / (a - c), ys = a * xs + b;
  v.dot(xs, ys, { r: 7 + Math.sin(t * 3), fill: H.colors.good });
  v.text("one x", xs + 0.3, ys + 0.6, { color: H.colors.good, size: 13 });
  label = "different slopes → lines CROSS once → exactly one solution x = " + xs.toFixed(2);
} else if (mode === 1) {
  label = "same slope, different intercept → PARALLEL → no solution (a·x+b never equals c·x+d)";
} else {
  label = "same slope AND intercept → SAME line → every x works → infinitely many solutions";
}
H.text(label, 24, 52, { color: (mode === 0 ? H.colors.sub : H.colors.warn), size: 12 });
// probe dot sweeping x, drawing the vertical gap between the two sides;
// the gap shrinks to 0 only where a solution exists.
const xp = 6 * Math.sin(t * 0.6);
const yl = a * xp + b, yr = c * xp + d;
v.dot(xp, yl, { r: 5, fill: H.colors.accent });
v.dot(xp, yr, { r: 5, fill: H.colors.accent2 });
v.line(xp, yl, xp, yr, { color: H.colors.violet, width: 1.5, dash: [3, 3] });
v.text("gap = " + Math.abs(yl - yr).toFixed(2), xp + 0.2, (yl + yr) / 2, { color: H.colors.violet, size: 12 });
